```cpp
#include <iostream>
#include <memory>
#include <string>
#include "src/cmark.h"

std::string markdownToHtml(const std::string& markdown) {
  struct output : public cmark_output {
    std::unique_ptr<char[]> buf;
    size_t len = 0;

    void append(const char* s, size_t n) override {
      if (len + n >= buf.size()) {
        buf.reset(new char[buf.size() * 2]);
      }

      std::copy(s, s + n, &buf.get()[len]);
      len += n;
    }

    const char* data() const override { return buf.get(); }
    size_t size() const override { return len; }
  };

  struct document doc;
  cmark_parse_doc(&doc, markdown.c_str(), markdown.size(), 0);

  output htmlOutput;
  cmark_render_html(&htmlOutput, &doc);

  std::string htmlResult(htmlOutput.data(), htmlOutput.size());
  cmark_free(doc.input);
  cmark_free(doc.output);
  cmark_free(doc.Allocator);

  return htmlResult;
}
